    private readonly int _cap;
    private readonly object _lock = new();
    public R9_BlockingQueue(int cap) => _cap = cap;

    public void Enqueue(T item) {
        lock (_lock) {
            if (_q.Count == _cap) Monitor.Wait(_lock);
            _q.Enqueue(item);
            Monitor.Pulse(_lock);
        }
    }

    public T Dequeue() {
        lock (_lock) {
            if (_q.Count == 0) Monitor.Wait(_lock);
            var item = _q.Dequeue();
            Monitor.Pulse(_lock);
